2.pdf","published_at":null,"accessed_at":"2026-11-05"},{"id":"src-ttkb-2025-05","title":"TTKB Kararı 09/05/2025 Sayı 05 — Anadolu/Fen/Sosyal Bilimler Lisesi (hazırlıklı dâhil) Haftalık Ders Çizelgeleri (2025-2026'dan itibaren tüm sınıflarda)","url":"https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_05/20144001_202505.pdf","published_at":"2025-05-09","accessed_at":"2026-11-05"},{"id":"src-tegm-2025-04","title":"TTKB Kararı 09/05/2025 Sayı 04 — İlköğretim Kurumları (İlkokul ve Ortaokul) Haftalık Ders Çizelgesi (TEGM duyurusu 29.07.2025)","url":"https://tegm.meb.gov.tr/www/ilkogretim-kurumlari-ilkokul-ve-ortaokul-haftalik-ders-cizelgesinde-degisiklik-yapildi/icerik/1150","published_at":"2025-07-29","accessed_at":"2026-11-05"}]}$j$::jsonb$seed$;
create function pg_temp.as_admin() returns void language sql as $$select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000010401","role":"authenticated","gina":{"role":"parent"}}',true)$$;
create function pg_temp.as_parent() returns void language sql as $$select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000010402","role":"authenticated","gina":{"role":"parent","family_id":"10000000-0000-4000-8000-000000010401"}}',true)$$;
create function pg_temp.as_stranger() returns void language sql as $$select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000010403","role":"authenticated","gina":{"role":"parent"}}',true)$$;
create function pg_temp.ids(j jsonb) returns text language sql immutable as $$select string_agg(x->>'subject_id',',' order by x->>'subject_id') from jsonb_array_elements(j->'candidates') x$$;

-- 1) Katalog: 20 yeni kimlik, mevcut 12 kimlik değişmedi, ekleme idempotent.
select is((select count(*)::int from public.guided_input_options where kind='subject'),32,'12 existing + 20 new subject ids');
select is((select count(*)::int from public.guided_input_options where id in('subject-german','subject-french','subject-religion','subject-inkilap','subject-pe','subject-visual-arts','subject-music','subject-ict','subject-technology-design','subject-traffic','subject-health-traffic','subject-rights','subject-guidance','subject-free-activities','subject-philosophy','subject-social-science-studies','subject-quran','subject-prophet-life','subject-basic-religious','subject-elective-other') and kind='subject' and active and revision=1),20,'all 20 proposed ids inserted, active, revision 1');
select is((select jsonb_agg(jsonb_build_array(id,label_tr,label_en,min_grade,max_grade,position,revision,active) order by id) from public.guided_input_options where kind='subject' and position<=120),
 '[["subject-biology","Biyoloji","Biology",9,12,90,1,true],["subject-chemistry","Kimya","Chemistry",9,12,80,1,true],["subject-english","İngilizce","English",2,12,60,1,true],["subject-geography","Coğrafya","Geography",9,12,110,1,true],["subject-history","Tarih","History",9,12,100,1,true],["subject-life","Hayat Bilgisi","Life Studies",1,3,50,1,true],["subject-literature","Türk Dili ve Edebiyatı","Turkish Language and Literature",9,12,120,1,true],["subject-math","Matematik","Mathematics",1,12,10,1,true],["subject-physics","Fizik","Physics",9,12,70,1,true],["subject-science","Fen Bilimleri","Science",3,8,30,1,true],["subject-social","Sosyal Bilgiler","Social Studies",4,7,40,1,true],["subject-turkish","Türkçe","Turkish",1,8,20,1,true]]'::jsonb,
 'existing 12 subject ids unchanged (labels, grade scope, position, revision)');
select is((select array[min_grade,max_grade] from public.guided_input_options where id='subject-inkilap'),array[8,12],'İnkılap grade scope 8–12');
select is((select array[min_grade,max_grade] from public.guided_input_options where id='subject-traffic'),array[4,4],'Trafik Güvenliği only grade 4');
-- Yönetici sonradan düzenlerse aynı ekleme tekrar çalıştırıldığında düzenlemeyi ezmez.
update public.guided_input_options set label_tr='Almanca (okulumuz)',revision=2 where id='subject-german';
insert into public.guided_input_options(id,kind,label_tr,label_en,min_grade,max_grade,position) values('subject-german','subject','Almanca','German',5,12,130),('subject-math','subject','Matematik X','Math X',1,1,999) on conflict (id) do nothing;
select is((select label_tr||'/'||revision from public.guided_input_options where id='subject-german'),'Almanca (okulumuz)/2','re-running id insert keeps admin edit (idempotent, do nothing)');
select is((select label_tr||'/'||max_grade from public.guided_input_options where id='subject-math'),'Matematik/12','re-running id insert never rewrites an existing id');
select is((select count(*)::int from gina.subject_synonyms),279,'279 synonym rows');
insert into gina.subject_synonyms(alias_normalized,alias,subject_id,grade_min,grade_max,source) select alias_normalized,alias,subject_id,grade_min,grade_max,source from gina.subject_synonyms on conflict do nothing;
select is((select count(*)::int from gina.subject_synonyms),279,'synonym insert is idempotent');
select is((select count(distinct subject_id)::int from gina.subject_synonyms where source='catalog'),32,'every canonical subject has synonyms');
select ok(not exists(select 1 from gina.subject_synonyms s where gina.normalize_subject_alias(s.alias)<>s.alias_normalized),'stored normalisation equals SQL normaliser');

-- 2) Normalizasyon (packages/core/src/subject-synonyms.test.ts ile aynı örnekler).
select is(gina.normalize_subject_alias('İNKILAP'),'inkilap','dotted capital I folds');
select is(gina.normalize_subject_alias('Fen Bil.'),'fenbil','dots and spaces removed');
select is(gina.normalize_subject_alias('Türkçe Dersi'),'turkce','"dersi" suffix dropped');
select is(gina.normalize_subject_alias('Kur''an-ı Kerim'),'kuranikerim','apostrophe and hyphen removed');
select is(gina.normalize_subject_alias('  Görsel   Sanatlar '),'gorselsanatlar','Turkish letters folded');
select is(gina.normalize_subject_alias('dersi'),'dersi','bare "dersi" is kept');

-- 3) suggest_subject: aday listesi, asla sessiz bağlama yok.
set local role authenticated;
select pg_temp.as_parent();
select is(public.suggest_subject('MAT',6)->>'match','single','MAT grade 6 -> single candidate');
select is(pg_temp.ids(public.suggest_subject('MAT',6)),'subject-math','MAT -> subject-math');
select is(public.suggest_subject('MAT',6)->'requires_confirmation','true'::jsonb,'single candidate still requires parent confirmation');
select ok(not (public.suggest_subject('MAT',6) ? 'subject_id'),'no top-level bound subject id');
select is(pg_temp.ids(public.suggest_subject('Fen Bil.',5)),'subject-science','Fen Bil. grade 5 -> Fen Bilimleri');
select is(public.suggest_subject('Fen',10)->>'match','ambiguous','Fen in grade 10 is ambiguous');
select is(pg_temp.ids(public.suggest_subject('Fen',10)),'subject-biology,subject-chemistry,subject-physics','grade scope narrows Fen to physics/chemistry/biology');
select is(pg_temp.ids(public.suggest_subject('Fen',5)),'subject-science','Fen in grade 5 -> science only');
select is(pg_temp.ids(public.suggest_subject('Sosyal',11)),'subject-social-science-studies','Sosyal in grade 11 -> Sosyal Bilim Çalışmaları');
select is(pg_temp.ids(public.suggest_subject('Sosyal',5)),'subject-social','Sosyal in grade 5 -> Sosyal Bilgiler');
select is(pg_temp.ids(public.suggest_subject('Din',7)),'subject-basic-religious,subject-prophet-life,subject-quran,subject-religion','Din offers four candidates');
select is(pg_temp.ids(public.suggest_subject('Din K.',7)),'subject-religion','Din K. -> DKAB');
select is(pg_temp.ids(public.suggest_subject('Yabancı Dil',4)),'subject-english,subject-french,subject-german','Yabancı Dil is asked, not assumed');
select is(pg_temp.ids(public.suggest_subject('İnkılap',8)),'subject-inkilap','İnkılap grade 8');
select is(pg_temp.ids(public.suggest_subject('İnkılap',10)),'subject-history','İnkılap in grade 10 suggests Tarih');
select is(public.suggest_subject('Bilişim',8)->'scope_note','true'::jsonb,'out-of-scope suggestion carries a note');
select is(public.suggest_subject('Bilişim',8)->'candidates'->0->'in_grade_scope','false'::jsonb,'ICT grade 8 is outside compulsory scope but not blocked');
select is(pg_temp.ids(public.suggest_subject('Halk Oyunları dersi',6)),'subject-elective-other','elective name -> Seçmeli ders (diğer)');
select is(public.suggest_subject('Uzay Kampı',6)->>'match','none','unknown label -> no candidate');
select is(public.suggest_subject('Uzay Kampı',6)->'keep_label','true'::jsonb,'unknown label is kept as typed');
select is(public.suggest_subject('...',null)->'candidates','[]'::jsonb,'punctuation only -> no candidates');
select is(pg_temp.ids(public.suggest_subject('beden',null)),'subject-pe','grade unknown -> candidates without narrowing');
select throws_ok($$select public.suggest_subject(repeat('a',81),5)$$,'P0001','subject_invalid','overlong input rejected');
select throws_ok($$select public.suggest_subject('MAT',13)$$,'P0001','subject_invalid','grade outside 0..12 rejected');
select throws_ok($$select public.admin_subject_synonyms()$$,'42501','forbidden','parent cannot list admin synonyms');
select throws_ok($$select public.admin_import_education_calendar_seed(gen_random_uuid(),pg_temp.seed(),false)$$,'42501','forbidden','parent cannot preview calendar seed');
select pg_temp.as_stranger();
select throws_ok($$select public.suggest_subject('MAT',6)$$,'42501','subject_forbidden','account without family cannot call suggest_subject');
reset role;
select ok(not has_function_privilege('anon','public.suggest_subject(text,int)','execute'),'anon cannot suggest subjects');
select ok(not has_function_privilege('anon','public.admin_import_education_calendar_seed(uuid,jsonb,boolean)','execute'),'anon cannot import calendars');
select ok(not has_function_privilege('authenticated','gina.normalize_subject_alias(text)','execute'),'normaliser is private');
select ok(not has_table_privilege('authenticated','gina.subject_synonyms','SELECT'),'synonym table not directly readable');
select is((select provolatile::text from pg_proc where oid='public.suggest_subject(text,int)'::regprocedure),'s','suggest_subject is STABLE (cannot write)');
-- Her eşanlamlı, kendi sınıf kapsamında bile onay ister.
select pg_temp.as_parent();
select ok((select bool_and((public.suggest_subject(alias,grade_min)->'requires_confirmation')::boolean) from gina.subject_synonyms),'every synonym result requires confirmation');
select ok((select bool_and(jsonb_array_length(public.suggest_subject(alias,grade_min)->'candidates')>=1) from gina.subject_synonyms),'every synonym finds its subject within scope');
update public.guided_input_options set active=false where id='subject-music';
select is(public.suggest_subject('Müzik',3)->>'match','none','inactive subject is never suggested');
update public.guided_input_options set active=true where id='subject-music';

-- 4) Takvim tohumu: önizleme yazmaz, yürütme yalnız taslak üretir, düşük güven atlanır.
-- Önceden var olan (yayımlanmış) bir takvime dokunulmaz.
insert into gina.education_calendars(id,place_id,stage,academic_year,draft,published,published_revision,published_at)
 select 'ca000000-0000-4000-8000-000000010401','ec000000-0000-4000-8000-000000000001','high',2026,v||'{"title":"Elle girilen lise takvimi"}',v||'{"title":"Elle girilen lise takvimi"}',1,now()
 from (select pg_temp.seed()->'calendars'->3->'calendar_value' v) x;
set local role authenticated;
select pg_temp.as_admin();
create temp table preview as select public.admin_import_education_calendar_seed(null,pg_temp.seed(),false) r;
select is((select r->'counts' from preview),'{"create":19,"exists":1,"skipped":4,"invalid":0,"new_places":4}'::jsonb,'preview: 19 drafts, 1 existing, 4 low-confidence skipped, 4 new regions');
select is((select r->'executed' from preview),'false'::jsonb,'preview does not execute');
select is((select string_agg(distinct x->>'place_name',',') from preview,jsonb_array_elements(r->'records') x where x->>'action'='skip'),'Düzce','only Düzce is skipped');
select is((select string_agg(distinct x->>'reason',',') from preview,jsonb_array_elements(r->'records') x where x->>'action'='skip'),'low_confidence','skip reason is low confidence');
select ok((select bool_and(x->>'source_url' ~ '^https://' and x->>'verified_on'='2026-11-05' and (x->>'terms')::int=4) from preview,jsonb_array_elements(r->'records') x where x->>'action'='create'),'every draft carries source url, check date and 4-part terms');
select is((select jsonb_array_length(r->'sources') from preview),14,'14 sources listed');
reset role;
select is((select count(*)::int from gina.education_calendars),1,'preview wrote nothing');
select is((select count(*)::int from gina.education_places where kind='region'),0,'preview created no places');
set local role authenticated;
select pg_temp.as_admin();
select throws_ok($$select public.admin_import_education_calendar_seed(gen_random_uuid(),pg_temp.seed()||'{"schema":"other"}',false)$$,'P0001','calendar_seed_invalid','unknown seed schema rejected');
select throws_ok($$select public.admin_import_education_calendar_seed(null,pg_temp.seed(),true)$$,'P0001','invalid_input','execution requires a request id');
select is(public.admin_import_education_calendar_seed('70000000-0000-4000-8000-000000010401',pg_temp.seed(),true)->'counts','{"create":19,"exists":1,"skipped":4,"invalid":0,"new_places":4}'::jsonb,'execute creates 19 drafts');
select is(public.admin_import_education_calendar_seed('70000000-0000-4000-8000-000000010401',pg_temp.seed(),true)->'counts'->>'create','19','same request replays the receipt');
select is(public.admin_import_education_calendar_seed('70000000-0000-4000-8000-000000010402',pg_temp.seed(),true)->'counts','{"create":0,"exists":20,"skipped":4,"invalid":0,"new_places":0}'::jsonb,'new request is idempotent: everything exists');
reset role;
select is((select count(*)::int from gina.education_calendars),20,'20 calendars in total (19 drafts + 1 pre-existing)');
select is((select count(*)::int from gina.education_calendars where published is not null),1,'import published nothing');
select is((select draft->>'title' from gina.education_calendars where id='ca000000-0000-4000-8000-000000010401'),'Elle girilen lise takvimi','pre-existing calendar untouched');
select is((select string_agg(name||':'||active,',' order by name) from gina.education_places where kind='region'),'Ankara:false,İstanbul:false,Kastamonu:false,Sivas:false','regions created hidden; Düzce not created');
select ok((select bool_and(draft->>'source_url' ~ '^https://' and draft->>'verified_on'='2026-11-05' and jsonb_array_length(draft->'terms')=4) from gina.education_calendars where published is null),'stored drafts keep source and check date');
select is((select count(*)::int from public.audit_log where action='education.calendar.draft' and details->>'source'='seed'),19,'each draft audited');
select is((select count(*)::int from public.audit_log where action='education.calendar.seed_import'),2,'each executed request audited once (replay adds none)');
select is(gina.education_calendar_match('ec000000-0000-4000-8000-000000000001','primary',2026),null::jsonb,'parents still see no imported calendar');
-- Yayın ayrı ve açık adımdır.
create temp table pub as select p.name,format('select public.admin_save_education_calendar(gen_random_uuid(),%L,1,%L,%L,2026,%L,true)',c.id,c.place_id,c.stage,c.draft) q
 from gina.education_calendars c join gina.education_places p on p.id=c.place_id where c.stage='primary' and p.name in('Türkiye','Ankara');
grant select on pub to authenticated;
set local role authenticated;
select pg_temp.as_admin();
select lives_ok((select q from pub where name='Türkiye'),'operator publishes the country primary draft explicitly');
select throws_ok((select q from pub where name='Ankara'),'P0001','calendar_invalid','hidden region must be activated before publishing');
reset role;
select is(gina.education_calendar_match('ec000000-0000-4000-8000-000000000001','primary',2026)->'value'->>'starts_on','2026-09-14','published country calendar is live only after explicit publish');
update public.operations_members set revoked_at=now() where user_id='00000000-0000-4000-8000-000000010401';
set local role authenticated;
select pg_temp.as_admin();
select throws_ok($$select public.admin_import_education_calendar_seed(null,pg_temp.seed(),false)$$,'42501','forbidden','revoked operator loses import access');
select throws_ok($$select public.suggest_subject('MAT',6)$$,'42501','subject_forbidden','revoked operator without family cannot suggest');
select * from finish();rollback;
